using LootEdit;
using LootEdit.loot;
using MonsterEdit.monsters;
using ProjectTower.audio;
using ProjectTower.config;
using ProjectTower.debug;
using ProjectTower.gamestate;
using ProjectTower.player;
using ProjectTower.player.randomizer;

namespace ProjectTower.character;

public class CharStats
{
	private Character c;

	public const float DEFENSE_FACTOR = 200f;

	public const float ARMOR_POISE_BLOCK_FACTOR = 40f;

	public const int WEIGHT_LIGHT = 0;

	public const int WEIGHT_MID = 1;

	public const int WEIGHT_MID_HEAVY = 2;

	public const int WEIGHT_HEAVY = 3;

	public const int WEIGHT_OVERBURDENED = 4;

	public const int DEF_BLUNT = 0;

	public const int DEF_FIRE = 1;

	public const int DEF_LIT = 2;

	public const int DEF_BLADED = 3;

	public const int DEF_POISON = 4;

	public const float ARMOR_POISE_ADJUST = 0.5f;

	public const int DEF_HOLY = 5;

	public const int DEF_DARK = 6;

	public const int ATK_PHYS = 0;

	public const int ATK_FIRE = 2;

	public const int ATK_LIT = 3;

	public const int ATK_POISON = 5;

	public const int ATK_BLADED = 6;

	public const int ATK_HOLY = 8;

	public const int ATK_DARK = 9;

	public CharStatsAttackVals attackVals;

	public CharStats(Character c)
	{
		this.c = c;
		attackVals = new CharStatsAttackVals(c);
	}

	public float GetSanctuaryMaxHP()
	{
		return c.GetPlayer()?.stats.GetHP() ?? 100f;
	}

	public float GetMaxHP()
	{
		if (c.playerIdx > -1)
		{
			float hP = c.GetPlayer().stats.GetHP();
			if (c.hpCapDmg > hP / 2f)
			{
				c.hpCapDmg = hP / 2f;
			}
			return hP - c.hpCapDmg;
		}
		MonsterDef obj = MonsterCatalog.catalog[c.monsterIdx];
		float num = obj.hp;
		Player mainPlayer = PlayerMgr.GetMainPlayer();
		if (mainPlayer != null && mainPlayer.IsScaledRandomizer())
		{
			num = RandomizerMgr.GetTierAdjustHp(c);
		}
		else if (GameModeMgr.IsGameEnhanced())
		{
			num = GetPlaythroughAdjustedBaseHp(c);
		}
		if (GameStateManager.coopPlayerIdx > -1)
		{
			num *= 1.5f;
		}
		if (GameStateManager.playthroughCount > 0 && !GameModeMgr.IsGameEnhanced())
		{
			num = num + num * 0.5f + num * 0.1f * (float)GameStateManager.playthroughCount + (float)(50 * GameStateManager.playthroughCount) + 80f;
			if (c.boss)
			{
				num += 2000f + (float)GameStateManager.playthroughCount * 500f;
			}
		}
		else if (GameStateManager.playthroughCount > 0 && GameModeMgr.IsGameEnhanced())
		{
			if (c.boss)
			{
				if (GameStateManager.playthroughCount > 1)
				{
					num += num * 0.07f * ((float)GameStateManager.playthroughCount - 1f) + ((float)GameStateManager.playthroughCount - 1f) * 400f;
				}
			}
			else
			{
				num = num + num * 0.5f + num * 0.1f * (float)GameStateManager.playthroughCount + (float)(50 * GameStateManager.playthroughCount) + 50f;
				if (GameStateManager.playthroughCount > 1)
				{
					num += 50f;
				}
			}
		}
		if (obj.name == "saltbat")
		{
			Player mainPlayer2 = PlayerMgr.GetMainPlayer();
			if (mainPlayer2 != null)
			{
				return mainPlayer2.stats.level;
			}
		}
		return num;
	}

	public float GetAdjustedDamage(float damage, int damageType)
	{
		float num = 0f;
		switch (damageType)
		{
		case 0:
			num = GetDefense(0);
			break;
		case 2:
			num = GetDefense(1);
			break;
		case 3:
			num = GetDefense(2);
			break;
		case 6:
			num = GetDefense(3);
			break;
		case 5:
			num = GetDefense(4);
			break;
		case 8:
			num = GetDefense(5);
			break;
		case 9:
			num = GetDefense(6);
			break;
		}
		if (c.equipment.active && c.buffs.GetProtect())
		{
			num *= 2f;
		}
		if (c.buffs.GetBloodied() && damageType != 8)
		{
			if (num > 0f)
			{
				num = 0f;
			}
			if (!GameModeMgr.IsGameEnhanced())
			{
				damage *= 1.25f;
			}
		}
		float num2 = 0f;
		num2 = num / (num + 200f);
		return damage - damage * num2;
	}

	public float GetDefense(int stat, PlayerStats stats)
	{
		float num = 0f;
		if (c.playerIdx > -1)
		{
			if (c.equipment.active)
			{
				Player player = c.GetPlayer();
				if (c.equipment.helm.catalogIdx > -1 && c.equipment.helm.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.helm.invIdx > -1 && stats.Equippable(LootCatalog.category[2].loot[c.equipment.helm.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.helm.invIdx].GetValue(stat, player);
				}
				if (c.equipment.armor.catalogIdx > -1 && c.equipment.armor.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.armor.invIdx > -1 && stats.Equippable(LootCatalog.category[2].loot[c.equipment.armor.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.armor.invIdx].GetValue(stat, player);
				}
				if (c.equipment.gloves.catalogIdx > -1 && c.equipment.gloves.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.gloves.invIdx > -1 && stats.Equippable(LootCatalog.category[2].loot[c.equipment.gloves.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.gloves.invIdx].GetValue(stat, player);
				}
				if (c.equipment.boots.catalogIdx > -1 && c.equipment.boots.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.boots.invIdx > -1 && stats.Equippable(LootCatalog.category[2].loot[c.equipment.boots.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.boots.invIdx].GetValue(stat, player);
				}
				num += GetPlayerLevelDefenseBonus(player, stat);
				if (stat == 7)
				{
					num *= 0.5f;
				}
				num += GetRingDefense(stat);
				if (c.buffs.GetWillBuff() > 0f && GameModeMgr.IsGameEnhanced() && stat == 7)
				{
					num *= 1.5f;
				}
			}
			switch (stat)
			{
			case 0:
			case 3:
			case 4:
				num += c.buffs.GetPhysDefBuff(23);
				if (c.buffs.GetGoldenBuff())
				{
					num = ((!GameModeMgr.IsGameEnhanced() || stat == 4 || c.playerIdx <= -1) ? (num + 200f) : (num + 200f));
				}
				break;
			case 1:
			case 2:
			case 5:
			case 6:
				num += c.buffs.GetPhysDefBuff(24);
				if (c.buffs.GetGoldenBuff())
				{
					num += 100f;
				}
				break;
			}
			if (c.buffs.GetProtect() && stat != 7)
			{
				num *= 2f;
			}
		}
		return num;
	}

	public bool GetCharmFlag(int flag)
	{
		int catalogIdx = c.equipment.loadout[c.equipment.loadoutIdx, 2].catalogIdx;
		int category = c.equipment.loadout[c.equipment.loadoutIdx, 2].category;
		if (catalogIdx > -1 && catalogIdx < LootCatalog.category[3].loot.Length && category == 3)
		{
			try
			{
				if (LootCatalog.category[3].loot[c.equipment.loadout[c.equipment.loadoutIdx, 2].catalogIdx].flags == flag)
				{
					return true;
				}

			}
		}
		catch
		{
		}
	}
	return false;
}

public bool GetCharmFlag(int flag, Player p, InvLoot replaceLoot)
{
	switch (p.playerInv.selItem)
	{
	case 4:
	case 5:
	case 6:
		if (c.equipment.loadoutIdx == 1)
		{
			return GetCharmFlag(flag);
		}
		break;
	case 7:
	case 8:
	case 9:
		if (c.equipment.loadoutIdx == 0)
		{
			return GetCharmFlag(flag);
		}
		break;
	}
	LootDef lootDef = LootCatalog.category[replaceLoot.category].loot[replaceLoot.catalogIdx];
	if (replaceLoot.category == 3 && lootDef.type == 1 && lootDef.category == 3 && lootDef.type == 1)
	{
		return lootDef.flags == flag;
	}
	return GetCharmFlag(flag);
}

public bool GetRingFlag(int flag)
{
	if (!c.equipment.active)
	{
		return false;
	}
	for (int i = 0; i < 4; i++)
	{
		if (c.equipment.ring[i].catalogIdx > -1 && c.equipment.ring[i].catalogIdx < LootCatalog.category[3].loot.Length && LootCatalog.category[3].loot[c.equipment.ring[i].catalogIdx].flags == flag)
		{
			return true;
		}
	}
	if (flag > 0 && c.playerIdx > -1)
	{
		Player player = c.GetPlayer();
		if (c.equipment.helm.catalogIdx > -1 && c.equipment.helm.catalogIdx < LootCatalog.category[2].loot.Length && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.helm.catalogIdx], -1) == 2 && LootCatalog.category[2].loot[c.equipment.helm.catalogIdx].special == flag)
		{
			return true;
		}
		if (c.equipment.armor.catalogIdx > -1 && c.equipment.armor.catalogIdx < LootCatalog.category[2].loot.Length && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.armor.catalogIdx], -1) == 2 && LootCatalog.category[2].loot[c.equipment.armor.catalogIdx].special == flag)
		{
			return true;
		}
		if (c.equipment.gloves.catalogIdx > -1 && c.equipment.gloves.catalogIdx < LootCatalog.category[2].loot.Length && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.gloves.catalogIdx], -1) == 2 && LootCatalog.category[2].loot[c.equipment.gloves.catalogIdx].special == flag)
		{
			return true;
		}
		if (c.equipment.boots.catalogIdx > -1 && c.equipment.boots.catalogIdx < LootCatalog.category[2].loot.Length && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.boots.catalogIdx], -1) == 2 && LootCatalog.category[2].loot[c.equipment.boots.catalogIdx].special == flag)
		{
			return true;
		}
		if (c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx > -1 && c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx < 128 && c.equipment.loadout[c.equipment.loadoutIdx, 1].category == 1 && c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx < LootCatalog.category[1].loot.Length && player.stats.Equippable(LootCatalog.category[1].loot[c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx], -1) == 2 && LootCatalog.category[1].loot[c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx].special == flag)
		{
			return true;
		}
	}
	return false;
}

public bool GetRingFlag(int flag, Player p, InvLoot replaceLoot)
{
	LootDef lootDef = LootCatalog.category[replaceLoot.category].loot[replaceLoot.catalogIdx];
	if (replaceLoot.category == 3 && lootDef.type == 0)
	{
		if (lootDef.category == 3 && lootDef.type == 0 && lootDef.flags == flag)
		{
			return true;
		}
		for (int i = 0; i < 4; i++)
		{
			if (i != p.playerInv.selItem - 16 && c.equipment.ring[i].catalogIdx != replaceLoot.catalogIdx && c.equipment.ring[i].catalogIdx > -1 && c.equipment.ring[i].catalogIdx < LootCatalog.category[3].loot.Length && LootCatalog.category[3].loot[c.equipment.ring[i].catalogIdx].flags == flag)
			{
				return true;
			}
		}
	}
	else if (GetRingFlag(flag))
	{
		return true;
	}
	return false;
}

private float GetRingDefense(int stat)
{
	float num = 0f;
	for (int i = 0; i < 4; i++)
	{
		if (c.equipment.ring[i].catalogIdx > -1 && c.equipment.ring[i].catalogIdx < LootCatalog.category[3].loot.Length)
		{
			LootDef lDef = LootCatalog.category[3].loot[c.equipment.ring[i].catalogIdx];
			num += GetRingDefense(stat, lDef);
			if (stat == 7 && num > 10f)
			{
				num = 10f;
			}
		}
	}
	return num;
}

public bool GetDropSuccess(float chance)
{
	Player player = c.GetPlayer();
	if (player != null)
	{
		float dropRate = player.stats.GetDropRate();
		if (!Rand.CoinToss(dropRate / (dropRate + 200f) * (chance / 100f)))
		{
			return DebugMgr.autoDrops;
		}
		return true;
	}
	return false;
}

private float GetRingDefense(int stat, LootDef lDef)
{
	float num = 0f;
	switch (stat)
	{
	case 0:
		if (lDef.flags == 0)
		{
			num += 50f;
		}
		break;
	case 1:
		if (lDef.flags == 2)
		{
			num += 50f;
		}
		break;
	case 2:
		if (lDef.flags == 1)
		{
			num += 50f;
		}
		break;
	case 4:
		if (lDef.flags == 3)
		{
			num += 50f;
		}
		break;
	case 3:
		if (lDef.flags == 4)
		{
			num += 50f;
		}
		break;
	case 5:
		if (lDef.flags == 5)
		{
			num += 50f;
		}
		break;
	case 6:
		if (lDef.flags == 6)
		{
			num += 50f;
		}
		break;
	case 7:
		if (lDef.flags == 13)
		{
			num += 10f;
		}
		break;
	}
	return num;
}

public float GetDefense(int stat)
{
	float num = 0f;
	if (c.playerIdx > -1)
	{
		if (c.equipment.active)
		{
			Player player = c.GetPlayer();
			if (player != null)
			{
				if (c.equipment.helm.catalogIdx > -1 && c.equipment.helm.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.helm.invIdx > -1 && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.helm.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.helm.invIdx].GetValue(stat, player);
				}
				if (c.equipment.armor.catalogIdx > -1 && c.equipment.armor.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.armor.invIdx > -1 && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.armor.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.armor.invIdx].GetValue(stat, player);
				}
				if (c.equipment.gloves.catalogIdx > -1 && c.equipment.gloves.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.gloves.invIdx > -1 && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.gloves.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.gloves.invIdx].GetValue(stat, player);
				}
				if (c.equipment.boots.catalogIdx > -1 && c.equipment.boots.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.boots.invIdx > -1 && player.stats.Equippable(LootCatalog.category[2].loot[c.equipment.boots.catalogIdx], -1) == 2)
				{
					num += player.playerInv.inventory[c.equipment.boots.invIdx].GetValue(stat, player);
				}
				num += GetRingDefense(stat);
				num += GetPlayerLevelDefenseBonus(player, stat);
			}
		}
		switch (stat)
		{
		case 0:
		case 3:
		case 4:
			num += c.buffs.GetPhysDefBuff(23);
			if (c.buffs.GetGoldenBuff())
			{
				num = ((!GameModeMgr.IsGameEnhanced() || stat == 4) ? (num + 200f) : (num + 200f));
			}
			break;
		case 1:
		case 2:
		case 5:
		case 6:
			num += c.buffs.GetPhysDefBuff(24);
			if (c.buffs.GetGoldenBuff())
			{
				num += 100f;
			}
			break;
		}
		return num;
	}
	MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
	return stat switch
	{
		0 => monsterDef.defense, 
		1 => monsterDef.fireDef, 
		2 => monsterDef.litDef, 
		4 => monsterDef.poisonDef, 
		3 => monsterDef.bladedDef, 
		5 => monsterDef.holyDef, 
		6 => monsterDef.darkDef, 
		_ => 0f, 
	};
}

public float GetDefense(int stat, Player p, InvLoot replaceLoot)
{
	LootDef lootDef = LootCatalog.category[replaceLoot.category].loot[replaceLoot.catalogIdx];
	float num = 0f;
	if (c.playerIdx > -1)
	{
		if (c.equipment.active)
		{
			if (replaceLoot.category == 2 && lootDef.type == 0)
			{
				if (p.stats.Equippable(lootDef, -1) == 2)
				{
					num += replaceLoot.GetValue(stat, p);
				}
			}
			else if (c.equipment.helm.catalogIdx > -1 && c.equipment.helm.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.helm.invIdx > -1 && p.stats.Equippable(LootCatalog.category[2].loot[c.equipment.helm.catalogIdx], -1) == 2)
			{
				num += p.playerInv.inventory[c.equipment.helm.invIdx].GetValue(stat, p);
			}
			if (replaceLoot.category == 2 && lootDef.type == 1)
			{
				if (p.stats.Equippable(lootDef, -1) == 2)
				{
					num += replaceLoot.GetValue(stat, p);
				}
			}
			else if (c.equipment.armor.catalogIdx > -1 && c.equipment.armor.catalogIdx < LootCatalog.category[2].loot.Length && c.equipment.armor.invIdx > -1 && p.stats.Equippable(LootCatalog.category[2].loot[c.equipment.armor.catalogIdx], -1) == 2)
			{
				num += p.playerInv.inventory[c.equipment.armor.invIdx].GetValue(stat, p);
			}
			if (replaceLoot.category == 2 && lootDef.type == 2)
			{
