		ParticleManager.AddNormalParticle(127, loc, default, p, 0f, attackType, c.ID);
	}

	public void ReduceHealth(float p)
	{
		float hp = c.hp;
		c.hp -= p;
		if (hp > 0f && c.hp <= 0f && c.grabbedByExe > -1)
		{
			c.hp = 1f;
