					break;
				default:
					if (type == 2)
					{
						num = Magic.GetScaledValue(10f, p, 1);
					}
					break;
				}
				break;
			}
		}
		float num2 = 0f;
		if (!particle.grounded && (particle.flags != 0 || particle.aux != 5) && particle.flags != 40)
		{
			if (c.equipment.loadout[c.equipment.loadoutIdx, 0].invIdx > -1)
			{
				num2 = p.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, 0].invIdx].GetScaledValue(0, p, p.stats, twoHanded: false, null);
			}
			if (c.equipment.loadout[c.equipment.loadoutIdx, 1].category == 0 && c.equipment.loadout[c.equipment.loadoutIdx, 1].catalogIdx > 128)
			{
				num2 = p.playerInv.inventory[c.equipment.loadout[c.equipment.loadoutIdx, 1].invIdx].GetScaledValue(0, p, p.stats, twoHanded: false, null);
			}
			num2 = 0.5f + num2 / 40f;
			num *= num2;
		}
		if (c.buffs.GetMagicBoost())
		{
			num *= 1.25f;
		}
		if ((type == 2 || type == 3) && num > 0f && c.stats.GetRingFlag(33) && !c.stats.GetRingFlag(34))
		{
