def validate_semantics(d: dict, strict: bool = False) -> list[str]:
    errs, seen = [], set()
    for sec in ("rules", "catalog"):
        for r in d.get(sec, []) or []:
            if r.get("id") in seen:
                errs.append(f"{sec}: дубликат id {r.get('id')}")
            seen.add(r.get("id"))
    if strict:
        if is_todo(d.get("goal", "")):
            errs.append("goal: TODO")
        for r in d.get("rules", []) or []:
            if is_todo(r.get("behavior")):
                errs.append(f"rule {r.get('id')}: behavior TODO")
            if not r.get("source_refs"):
                errs.append(f"rule {r.get('id')}: нет source_refs")
        for r in d.get("catalog", []) or []:
            if is_todo(r.get("own_name")) or is_todo(r.get("behavior", "x")):
                errs.append(f"catalog {r.get('id')}: own_name/behavior TODO")
        if d.get("candidates"):
            errs.append(f"candidates: осталось {len(d['candidates'])} — превратить в rules/catalog и удалить")
    return errs


def merge_by_system(recs: list[dict]) -> list[dict]:
    """Файлы с одинаковым system.id склеиваются: списки конкатенируются, goal — первый непустой."""
    by: dict[str, dict] = {}
    for r in recs:
        sid = r["system"]["id"]
        m = by.get(sid)
        if m is None:
            m = {"schema": r["schema"], "game": r["game"], "system": dict(r["system"]), "goal": "", "rules": [],
                 "catalog": [], "open_questions": [], "acceptance": [], "status": r.get("status", "draft"),
                 "_paths": []}
            by[sid] = m
        if not m["goal"] or is_todo(m["goal"]):
            m["goal"] = r.get("goal", "") or m["goal"]
        for k in ("rules", "catalog", "open_questions", "acceptance"):
            items = r.get(k, []) or []
            if k in ("rules", "catalog") and r.get("collection"):
                items = [({"collection": r["collection"], **it}) for it in items]  # коллекция файла -> строкам
            m[k] += items
        rank = {"skeleton": 0, "draft": 1, "reviewed": 2}
        if rank[r.get("status", "draft")] > rank[m["status"]]:
            m["status"] = r.get("status", "draft")
        m["_paths"].append(r.get("_path", ""))
        for b in r["system"].get("buckets", []) or []:
            m["system"].setdefault("buckets", [])
            if b not in m["system"]["buckets"]:
                m["system"]["buckets"].append(b)
    return [by[k] for k in sorted(by)]


def load_records(paths, validate: bool = True) -> list[dict]:
    recs = []
    for p in find_files(paths):
        d = load_file(p)
        if validate:
            errs = validate_schema(d)
            if errs:
                raise ValueError(f"{p}: схема:\n  " + "\n  ".join(errs))
        recs.append(d)
    return recs


